DROP TABLE IF EXISTS `kyc_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `kyc_records` (
  `kyc_id` varchar(15) NOT NULL,
  `customer_id` varchar(10) DEFAULT NULL,
  `kyc_status` varchar(30) DEFAULT NULL,
  `verification_date` date DEFAULT NULL,
  `expiry_date` date DEFAULT NULL,
  `document_type` varchar(50) DEFAULT NULL,
  `verification_method` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`kyc_id`),
  KEY `customer_id` (`customer_id`),
  CONSTRAINT `kyc_records_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`customer_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
